      'bill': bill.toJson(),
      'amountPaid': amountPaid,
      'datePaid': datePaid.toIso8601String(),
      'paymentMethod': paymentMethod,
      'notes': notes
    });
    return SupplierPayment.fromMap((res as Map).cast<String, dynamic>());
  }

  @override
  Future<List<SupplierPayment>> getPaymentsForBill(String billId) async {
    final res = await _rpc
        .call('supplierPayment.getPaymentsForBill', {'billId': billId});
    return [
      for (final x0 in res as List)
        SupplierPayment.fromMap((x0 as Map).cast<String, dynamic>())
    ];
  }

  @override
  Future<double> getTotalPaidForBill(String billId) async {
    final res = await _rpc
        .call('supplierPayment.getTotalPaidForBill', {'billId': billId});
    return (res as num).toDouble();
  }

  @override
  Future<Map<String, double>> getTotalPaidBatch(List<String> billIds) async {
    final res = await _rpc
        .call('supplierPayment.getTotalPaidBatch', {'billIds': billIds});
    return (res as Map)
        .map((k0, v0) => MapEntry(k0 as String, (v0 as num).toDouble()));
  }

  @override
  Future<void> deletePayment(String paymentId) async {
    await _rpc.call('supplierPayment.deletePayment', {'paymentId': paymentId});
  }
}

